class LowerCapture(Flowable):
 def __init__(self,path,width=256):
  super().__init__();self.image=ImageReader(str(path));self.iw,self.ih=self.image.getSize();self.width=width;self.scale=width/self.iw;self.height=290*self.scale
 def draw(self):
  c=self.canv;c.saveState();clip=c.beginPath();clip.rect(0,0,self.width,self.height);c.clipPath(clip,stroke=0)
  c.drawImage(self.image,0,-(self.ih-810)*self.scale,width=self.iw*self.scale,height=self.ih*self.scale);c.restoreState()
def fitted(path,width):
 image=ImageReader(str(path));w,h=image.getSize();return Image(str(path),width=width,height=width*h/w)
